detector_raw:
{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this packing plan — for example, minimize the number of containers used, maximize the total weight of goods shipped, or something else?"
  ],
  "rationale": "The response contains a single clarification question asking for the specific objective of the packing plan, presented as a choice among examples."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Do all available goods have to be shipped, or is it acceptable to leave some units of any type unshipped?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice regarding whether all goods must be shipped or if unshipped units are permitted."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there a fixed number of containers available to choose from, or can we assume an unlimited supply of identical containers?"
  ],
  "rationale": "The response asks a single clarification question regarding the availability of containers, presenting two mutually exclusive options for the user to choose from."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there a limit on the number of units of each goods type that can be loaded into a single container, or is the only per-container restriction the 18–60 ton weight range and the minimum of 12 units of type D?"
  ],
  "rationale": "The response asks a single clarification question regarding per-container unit limits versus weight/type restrictions."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the goods units of each type identical and interchangeable, so that any unit of a given type can go into any container?"
  ],
  "rationale": "The response contains a single clarification question asking about the interchangeability of goods units within a type."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the 18-ton minimum weight requirement applied to every container that is used, including the last container which may be only partially filled?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy decision about the scope of the weight requirement."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Since leaving goods unshipped is allowed, is there any requirement that a minimum amount of goods must be shipped, or is it acceptable to ship zero goods and use zero containers?"
  ],
  "rationale": "The response asks a single clarification question regarding whether a minimum shipment quantity is required or if zero shipment is acceptable. Although it presents two options, it seeks a single policy decision."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the unit weights and available quantities exact, so that the total weight of a container is computed as the sum of (units × unit weight) for each type loaded in it?"
  ],
  "rationale": "The response contains a single clarification question asking for confirmation of the calculation method and data precision."
}
